// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess(hash);

        // The reference C sets the guess and block after accepting 1 ether.
        // The mutant requires 2 ether, so with 1 ether the call would revert,
        // meaning the caller's guess block remains 0.
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("guesses(address)", caller));
        uint blockNumber;
        bytes32 storedGuess;
        (storedGuess, blockNumber) = abi.decode(data, (bytes32, uint));

        // General rule: after a successful lockInGuess with exactly 1 ether,
        // the caller's guess block should be block.number + 1.
        assertTrue(blockNumber == block.number + 1);
    }
}

