        c.lockInGuess{value: 1 ether}(guessHash);

        // Mine to a block where the guessHash could be the blockhash
        vm.roll(block.number + 1);

        uint256 balanceBefore = address(this).balance;
        // Attempt to settle
        (bool settleOk, ) = address(c).call(abi.encodeWithSignature("settle()"));
        uint256 balanceAfter = address(this).balance;

        // The original function: if guessHash == blockhash, then transfer 2 ether should NOT happen
        // Because in the reference, correct guess should NOT transfer, but buggy version does
        // To make it general: we consider the case where guessHash == blockhash
        // Since we cannot control blockhash, we assume it could match
        // The rule: if settle succeeded, the balance should not increase (no transfer for correct guess)
        // Actually the reference never transfers for correct guess, so balance doesn't change
