pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash) public {
        vm.assume(address(c).balance >= 2 ether);

        address player = address(this);
        vm.deal(player, 1 ether);

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);

        uint256 predictedBlock = c.guesses(player).block;

        vm.roll(predictedBlock + 1);

        uint256 balanceBefore = address(c).balance;
        c.settle();
        uint256 balanceAfter = address(c).balance;

        bytes32 blockhashAtPredicted = blockhash(predictedBlock);

        if (blockhashAtPredicted != 0 && hash == blockhashAtPredicted) {
            assertTrue(balanceAfter == balanceBefore, "Transfer should not occur when guess equals blockhash");
        }
    }
}

