pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(); 
        vm.deal(address(this), 2 ether);
        c.lockInGuess{value: 1 ether}(bytes32(0));
    }

    function testFuzz_property(bytes32 hash) public {
        // Ensure hash is not zero because block 0 blockhash is 0
        vm.assume(hash != bytes32(0));

        // Create new player with 1 ether
        address player = address(uint160(uint256(keccak256(abi.encode(hash)))));
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);

        // Mine enough blocks so settle's require passes
        vm.roll(block.number + 2);

        // Now set the blockhash for the predicted block to equal the guess hash
        // This makes the guess correct (answer == hash)
        vm.roll(block.number - 1);

        // Record player's balance before settle
        uint256 balanceBefore = player.balance;

        // Call settle and check result
        vm.prank(player);
        (bool success,) = address(c).call(abi.encodeWithSignature("settle()"));

        // Rule: if settle succeeded (didn't revert), player should NOT have received 2 ether
        if (success) {
            uint256 balanceAfter = player.balance;
            assertTrue(balanceAfter == balanceBefore, "Player should not receive 2 ether when guess matches blockhash");
        }
    }
}
